    }
  ],
  "relations": [
    {
      "from": "inventory_unit",
      "to": "inventory_ledger",
      "type": "1:N",
      "label": "产生流水",
      "color": "#E8833A",
      "penwidth": 1.4
    },
    {
      "from": "inventory_unit",
      "to": "channel_inventory_allocation",
      "type": "1:N",
      "label": "分配到渠道",
      "color": "#8E24AA",
      "penwidth": 1.4
    },
    {
      "from": "inventory_unit",
      "to": "warehouse",
      "type": "N:1",
      "label": "所在仓库",
      "color": "#43A047"
    },
    {
      "from": "inventory_unit",
      "to": "product",
      "type": "N:1",
      "label": "关联实物商品",
      "style": "dashed",
      "color": "#999999"
    },
    {
      "from": "channel_inventory_allocation",
      "to": "channel",
      "type": "N:1",
      "label": "所属渠道",
      "style": "dashed",
      "color": "#999999"
    },
    {
      "from": "channel_inventory_allocation",
      "to": "listing",
      "type": "N:1",
      "label": "关联渠道商品",
      "style": "dashed",
      "color": "#999999"
    },
    {
      "from": "warehouse",
      "to": "market",
      "type": "N:1",
      "label": "所属Market",
      "style": "dashed",
      "color": "#999999"
    }
  ],
  "design_rules": {
    "库存单元": "inventory_unit 是库存管理最小单元，直接关联商品系统的 product；一物一码 quantity=1，标品 quantity≥1",
    "三层架构": "仓内实物库存层（物理位置）→ 中央库存层（全盘资产）→ 渠道库存层（多渠道售卖）",
    "流水台账": "每次库存变动记录一条 inventory_ledger 流水，quantity_change 记录数量变化（一物一码±1，标品±N）",
    "多渠道售卖": "同一库存单元可分配到多渠道；一物一码下单时排他预占，标品按数量分配",
    "渠道数量拆分": "allocated_quantity = available_quantity + reserved_quantity + locked_quantity",
    "预占超时释放": "reserve_expire_at + 定时任务扫描，超时未支付自动释放预占数量",
    "状态分离": "inventory_status（物理流转）与商品系统的 item_status（业务生命周期）分离管理，事件驱动同步",
    "分仓管理": "一个 product 可有多个 inventory_unit 分布在不同仓库，SUM(quantity) = product 总库存",
    "外部引用": "product/channel/listing/market 为商品系统和Market主数据的外部实体，虚线表示跨模块引用"
  }
}
